void ScintillaEditFixed::replaceSel(const QString &text) {
	const QByteArray textBytes = bytesForDocument(*this, text);
	if (textBytes.contains('\0')) {
		send(SCI_BEGINUNDOACTION, 0, 0);
		send(SCI_REPLACESEL, 0, reinterpret_cast<qint64>(""));
		send(SCI_ADDTEXT, textBytes.size(), reinterpret_cast<qint64>(textBytes.constData()));
		send(SCI_SCROLLCARET, 0, 0);
		send(SCI_ENDUNDOACTION, 0, 0);
		return;
	}
	send(SCI_REPLACESEL, 0, reinterpret_cast<qint64>(textBytes.constData()));
}

